import React, { useEffect, useState } from "react";
import Header from "./Header";
import { useNavigate } from "react-router-dom";
import axios from "axios";

export default function TechnicianDashboard() {
  const navigate = useNavigate();
  const [issues, setIssues] = useState([]);
  const [user, setUser] = useState({ name: "", email: "" });

  useEffect(() => {
    const userStr = localStorage.getItem("user");
    if (userStr) {
      const u = JSON.parse(userStr);
      setUser(u);
      const token = localStorage.getItem("token");
      const config = token ? { headers: { Authorization: `Bearer ${token}` } } : {};
      axios.get(`http:lo/api/issues/assigned/${u._id || u.id}`, config)
        .then(res => setIssues(res.data))
        .catch(() => setIssues([]));
    }
  }, []);

  // Status counts
  const statusCounts = issues.reduce((acc, issue) => {
    const status = (issue.tags && issue.tags.find(t => ["PENDING", "IN PROGRESS", "COMPLETED", "OVERDUE"].includes(t.toUpperCase()))) || "PENDING";
    acc[status.toUpperCase()] = (acc[status.toUpperCase()] || 0) + 1;
    return acc;
  }, { PENDING: 0, "IN PROGRESS": 0, COMPLETED: 0, OVERDUE: 0 });

  // Recent issues (sorted by createdAt desc)
  const recentIssues = [...issues].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)).slice(0, 5);

  return (
    <div className="min-h-screen bg-gray-50 p-4 md:p-8">
      <nav className="flex items-center justify-between bg-white shadow px-4 md:px-8 h-16 mb-8">
        <div className="flex items-center gap-3">
          <span className="bg-indigo-600 rounded-xl p-1 flex items-center justify-center">
            <svg width="36" height="36" viewBox="0 0 24 24" fill="none"><rect x="2" y="2" width="20" height="20" rx="6" fill="#6366f1"/><rect x="6" y="6" width="12" height="6" rx="2" fill="#a5b4fc"/></svg>
          </span>
          <div className="flex flex-col ml-1">
            <span className="text-lg font-bold text-gray-900">PropCare</span>
            <span className="text-sm text-gray-500">{user.name}</span>
          </div>
        </div>
        <div className="flex gap-2 md:gap-3">
          <button className="flex items-center gap-2 px-4 py-2 rounded-lg bg-indigo-100 text-indigo-700 font-semibold" disabled>
            Dashboard
          </button>
          <button className="flex items-center gap-2 px-4 py-2 rounded-lg hover:bg-gray-100 font-semibold" onClick={() => navigate('/issues')}>
            All Issues
          </button>
        </div>
      </nav>
      <Header
        title={`Welcome back, ${user.name || "Technician"}!`}
        subtitle={<span className="bg-purple-100 text-purple-700 text-xs md:text-base rounded-full px-2 md:px-4 py-1 font-medium">Showing issues assigned to you</span>}
        right={<span className="text-gray-500 text-base md:text-lg">Overview</span>}
        className="mb-6"
      />
      {/* Status Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 md:gap-6 mb-8">
        <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-6 flex flex-col items-start">
          <span className="text-yellow-700 font-semibold mb-1">Pending</span>
          <span className="text-3xl font-bold">{statusCounts.PENDING}</span>
          <span className="text-yellow-400 mt-2"><svg width="32" height="32" fill="none" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" stroke="#fde68a" strokeWidth="2"/><path d="M12 8v4l2 2" stroke="#b45309" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
        </div>
        <div className="bg-blue-50 border border-blue-200 rounded-xl p-6 flex flex-col items-start">
          <span className="text-blue-700 font-semibold mb-1">In Progress</span>
          <span className="text-3xl font-bold">{statusCounts["IN PROGRESS"]}</span>
          <span className="text-blue-400 mt-2"><svg width="32" height="32" fill="none" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" stroke="#dbeafe" strokeWidth="2"/><path d="M12 8v4l2 2" stroke="#2563eb" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
        </div>
        <div className="bg-green-50 border border-green-200 rounded-xl p-6 flex flex-col items-start">
          <span className="text-green-700 font-semibold mb-1">Completed</span>
          <span className="text-3xl font-bold">{statusCounts.COMPLETED}</span>
          <span className="text-green-400 mt-2"><svg width="32" height="32" fill="none" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" stroke="#d1fae5" strokeWidth="2"/><path d="M9 12l2 2 4-4" stroke="#059669" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
        </div>
        <div className="bg-red-50 border border-red-200 rounded-xl p-6 flex flex-col items-start">
          <span className="text-red-700 font-semibold mb-1">Overdue</span>
          <span className="text-3xl font-bold">{statusCounts.OVERDUE}</span>
          <span className="text-red-400 mt-2"><svg width="32" height="32" fill="none" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" stroke="#fee2e2" strokeWidth="2"/><path d="M15 9l-6 6M9 9l6 6" stroke="#dc2626" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></span>
        </div>
      </div>
      {/* Recent Issues */}
      <div className="bg-white rounded-2xl shadow p-0 mb-6 md:mb-8 w-full">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between px-4 md:px-6 pt-4 md:pt-6 pb-2 gap-2">
          <span className="text-lg md:text-xl font-semibold flex items-center gap-2">
            Recent Issues
          </span>
          <a href="#" className="text-indigo-600 font-medium hover:underline" onClick={e => { e.preventDefault(); navigate('/issues'); }}>View All Issues →</a>
        </div>
        <div className="px-4 md:px-6 pb-4">
          {recentIssues.length === 0 && <div className="text-gray-400 text-center py-8">No issues assigned yet.</div>}
          {recentIssues.map((issue, idx) => (
            <div className="flex flex-col md:flex-row items-start justify-between border-t border-gray-100 py-4 md:py-5 gap-4 md:gap-6 transition hover:bg-gray-50" key={idx}>
              <div className="flex-1">
                <div className="text-base md:text-lg font-semibold mb-1">{issue.title}</div>
                <div className="text-gray-500 mb-2">{issue.location}</div>
                <div className="flex gap-2 mb-1 flex-wrap">
                  {issue.tags && issue.tags.map((tag, i) => (
                    <span className={`rounded-md px-2 md:px-3 py-1 text-xs md:text-sm font-medium ${tag === 'URGENT' ? 'bg-red-100 text-red-600' : tag === 'IN PROGRESS' ? 'bg-blue-100 text-blue-600' : tag === 'COMPLETED' ? 'bg-green-100 text-green-600' : tag === 'PENDING' ? 'bg-gray-100 text-gray-600' : tag === 'OVERDUE' ? 'bg-red-100 text-red-600' : 'bg-gray-100 text-gray-700'}`} key={i}>{tag}</span>
                  ))}
                </div>
              </div>
              <div className="flex flex-col items-end min-w-[70px] md:min-w-[90px] gap-1">
                {issue.time && (
                  <span className="flex items-center gap-1 text-yellow-700 text-xs md:text-base font-medium"><span role="img" aria-label="warning">⚠️</span> {issue.time}</span>
                )}
                {issue.overdue && <span className="text-red-600 text-xs md:text-sm font-semibold">overdue</span>}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
